const input = $input.first().json;
const out = [];
for (const [company_key, byWindow] of Object.entries(input.signals_by_company_key || {})) {
  const s24 = byWindow['24h'] || {}; const s7 = byWindow['7d'] || {}; const s30 = byWindow['30d'] || {};
  const daily7 = (s7.active_offer_count || 0) / 7;
  const cold = (s7.active_offer_count || 0) === 0 && (s30.active_offer_count || 0) === 0;
  const acceleration = cold ? null : Math.min(input.ratio_cap, (s24.active_offer_count || 0) / Math.max(daily7, 1));
  const recurrence = (s30.republication_count || 0) / Math.max((s30.active_offer_count || 0) + (s30.republication_count || 0), 1);
  const diversity = (s30.job_family_count || 0) / Math.max(s30.active_offer_count || 0, 1);
  const multisite = (s30.site_count || 0) >= 2;
  const labels = [];
  if (cold) labels.push('cold_start');
  else if (acceleration >= 2 && recurrence < 0.35) labels.push('campaign');
  if (recurrence >= 0.35) labels.push('continuous_need');
  if (multisite) labels.push('multi_site');
  if (diversity < 0.25) labels.push('focused');
  out.push({ derived_signal_key: `${company_key}:${input.derived_signal_version}:${input.now_utc}`, company_key, derived_signal_version: input.derived_signal_version, acceleration_index: acceleration, diversity_index: diversity, multisite_index: s30.site_count || 0, recurrence_rate: recurrence, labels_json: JSON.stringify(labels), confidence: cold ? 0.6 : 0.8, source_signal_keys_json: JSON.stringify([s24.signal_key, s7.signal_key, s30.signal_key].filter(Boolean)), computed_at: input.now_utc });
}
return [{ json: { ...input, company_derived_signal_upserts: out } }];
